/* ============================================================
   CRYOUT — dynamic 3D rhythm
   ============================================================ */
:root{
  --bg:#04040c;
  --ink:#eaf6ff;
  --muted:#8393ab;
  --cyan:#5ee7ff;
  --magenta:#ff5fd2;
  --violet:#9374ff;
  --panel:rgba(8,12,26,.58);
  --line:rgba(148,190,255,.18);
  --mono:ui-monospace,"DejaVu Sans Mono","Liberation Mono",Menlo,Consolas,monospace;
  --sans:Lato,"DejaVu Sans","Liberation Sans",system-ui,sans-serif;
}

*{box-sizing:border-box}
html,body{height:100%;margin:0;background:var(--bg);color:var(--ink);overflow:hidden}
body{
  font-family:var(--sans);
  -webkit-font-smoothing:antialiased;
  overscroll-behavior:none;
  user-select:none;
  -webkit-user-select:none;
  -webkit-tap-highlight-color:transparent;
}
button{font:inherit;color:inherit;border:0;background:none;cursor:pointer}
#scene{position:fixed;inset:0;width:100%;height:100%;display:block;touch-action:none}

#vignette{
  position:fixed;inset:0;pointer-events:none;z-index:1;
  background:
    radial-gradient(ellipse at 50% 44%, transparent 28%, rgba(2,2,9,.28) 66%, rgba(1,1,6,.82) 100%),
    linear-gradient(180deg, rgba(1,1,6,.55) 0%, transparent 18%, transparent 72%, rgba(1,1,6,.7) 100%);
  mix-blend-mode:multiply;
}
#vignette::after{
  content:"";position:absolute;inset:0;opacity:.16;pointer-events:none;
  background-image:repeating-linear-gradient(0deg, rgba(255,255,255,.08) 0 1px, transparent 1px 3px);
  mix-blend-mode:overlay;
}

#app{position:relative;z-index:2;height:100%;width:100%}
.hidden{display:none !important}

/* ---------------- HUD ---------------- */
#hud{
  position:absolute;inset:0;pointer-events:none;
  padding:clamp(14px,2.2vw,30px);
  display:flex;flex-direction:column;
}
.topbar{
  display:grid;grid-template-columns:minmax(140px,1fr) minmax(240px,2.2fr) minmax(160px,1fr);
  align-items:start;gap:clamp(14px,3vw,54px);
}
.brand-title{
  font-weight:900;font-size:clamp(19px,2vw,27px);letter-spacing:.2em;line-height:1;
  text-shadow:0 0 22px rgba(94,231,255,.45);
}
.brand-sub{
  margin-top:7px;font-size:9px;letter-spacing:.22em;color:var(--muted);font-family:var(--mono);
}
.brand-sub span{color:var(--cyan)}

.track-wrap{align-self:start;padding-top:4px}
.progress{
  position:relative;height:4px;background:rgba(130,170,230,.14);
  box-shadow:0 0 0 1px rgba(140,190,255,.08) inset;overflow:hidden;
}
.progress b{
  position:absolute;inset:0 auto 0 0;width:0%;
  background:linear-gradient(90deg,var(--cyan),var(--violet) 55%,var(--magenta));
  box-shadow:0 0 16px var(--cyan);transition:width .08s linear;
}
.progress span{
  position:absolute;top:-3px;width:10px;height:10px;border-radius:50%;left:0%;
  background:#fff;box-shadow:0 0 14px 3px var(--cyan);transform:translateX(-50%);
  transition:left .08s linear;
}
.trackmeta{
  display:flex;justify-content:space-between;margin-top:10px;
  font-family:var(--mono);font-size:9px;letter-spacing:.2em;color:var(--muted);
}
#sectionName{color:var(--cyan);text-shadow:0 0 12px rgba(94,231,255,.6)}
.scoreblock{text-align:right}
.score{
  font-family:var(--mono);font-size:clamp(22px,2.4vw,32px);font-weight:700;letter-spacing:.08em;
  line-height:1;font-variant-numeric:tabular-nums;
  text-shadow:0 0 24px rgba(94,231,255,.28);
}
.acc{margin-top:8px;font-family:var(--mono);font-size:9px;letter-spacing:.16em;color:var(--muted)}
.acc .dot{margin:0 6px;color:rgba(255,255,255,.3)}
#acc{color:#cfeaff}

.left-hud{
  position:absolute;left:clamp(14px,2.2vw,30px);bottom:clamp(112px,15vh,160px);
  display:flex;flex-direction:column;gap:18px;align-items:flex-start;
}
.lane-count{display:flex;align-items:baseline;gap:7px;font-family:var(--mono)}
.lane-count span{
  font-size:clamp(26px,3vw,40px);font-weight:700;line-height:1;
  color:var(--cyan);text-shadow:0 0 22px rgba(94,231,255,.55);
}
.lane-count small{font-size:8px;letter-spacing:.24em;color:var(--muted)}
.sync{display:flex;align-items:center;gap:9px}
.sync-label{font-family:var(--mono);font-size:8px;letter-spacing:.2em;color:var(--muted);writing-mode:vertical-rl;transform:rotate(180deg)}
.energy{
  width:3px;height:82px;background:rgba(150,190,255,.15);position:relative;overflow:hidden;
}
.energy i{
  position:absolute;inset:auto 0 0 0;height:100%;
  background:linear-gradient(0deg,var(--magenta),var(--violet),var(--cyan));
  box-shadow:0 0 12px var(--cyan);transition:height .2s ease;
}
#comboHud{
  position:absolute;left:50%;top:43%;transform:translate(-50%,-50%) scale(.9);
  text-align:center;opacity:0;transition:opacity .2s ease, transform .2s ease;
  pointer-events:none;
}
#comboHud.on{opacity:.94;transform:translate(-50%,-50%) scale(1)}
#comboHud b{
  display:block;font-family:var(--mono);font-size:clamp(42px,6vw,84px);line-height:.85;
  font-weight:800;letter-spacing:-.03em;color:#fff;
  text-shadow:0 0 24px rgba(94,231,255,.78), 0 0 70px rgba(147,116,255,.4);
  font-variant-numeric:tabular-nums;
}
#comboHud span{
  display:block;margin-top:8px;font-family:var(--mono);font-size:9px;letter-spacing:.5em;
  color:var(--cyan);text-indent:.5em;
}
#comboHud.bump b{animation:bump .18s ease}
@keyframes bump{0%{transform:scale(1)}42%{transform:scale(1.13)}100%{transform:scale(1)}}

#judge{
  position:absolute;left:50%;top:57%;transform:translate(-50%,-50%);
  font-family:var(--mono);font-size:clamp(13px,1.5vw,18px);letter-spacing:.4em;
  color:#fff;opacity:0;text-transform:uppercase;white-space:nowrap;
  text-indent:.4em;text-shadow:0 0 22px currentColor;
  pointer-events:none;
}
#judge.pop{animation:judgePop .45s cubic-bezier(.2,.75,.2,1) both}
@keyframes judgePop{
  0%{opacity:0;transform:translate(-50%,-50%) scale(.72)}
  16%{opacity:1;transform:translate(-50%,-50%) scale(1.03)}
  62%{opacity:1;transform:translate(-50%,-62%) scale(1)}
  100%{opacity:0;transform:translate(-50%,-80%) scale(.98)}
}
#judge.perfect{color:#a9f6ff}
#judge.great{color:#73e6ff}
#judge.good{color:#a8a5ff}
#judge.bad{color:#ff9b6a}
#judge.miss{color:#ff4e75}

#pauseBtn{
  position:absolute;right:clamp(14px,2.2vw,30px);bottom:calc(clamp(14px,2.2vw,30px) + 78px);
  width:42px;height:42px;border:1px solid var(--line);border-radius:50%;
  background:rgba(8,12,26,.5);backdrop-filter:blur(8px);
  color:var(--muted);font-size:11px;pointer-events:auto;letter-spacing:.08em;
  transition:.2s;
}
#pauseBtn:hover{border-color:var(--cyan);color:var(--cyan);box-shadow:0 0 20px rgba(94,231,255,.25)}

/* ---------------- touch / key pads ---------------- */
#pads{
  position:absolute;left:50%;bottom:max(12px,env(safe-area-inset-bottom));
  transform:translateX(-50%);
  width:min(760px,calc(100% - 28px));
  display:grid;grid-template-columns:repeat(8,1fr);gap:6px;
  pointer-events:auto;touch-action:none;
}
.pad{
  height:clamp(40px,6.4vh,56px);position:relative;overflow:hidden;
  border:1px solid rgba(140,190,255,.16);border-radius:5px;
  background:linear-gradient(180deg,rgba(18,26,52,.5),rgba(5,8,20,.6));
  backdrop-filter:blur(6px);
  transition:border-color .12s, background .12s, box-shadow .12s, opacity .3s;
  touch-action:none;
}
.pad::before{
  content:"";position:absolute;inset:auto 0 0 0;height:2px;
  background:currentColor;opacity:.35;transition:.12s;
}
.pad .pk{
  position:relative;z-index:1;font-family:var(--mono);font-size:11px;letter-spacing:.05em;
  color:var(--muted);transition:.12s;
}
.pad i{
  position:absolute;inset:0;background:radial-gradient(ellipse at 50% 120%,currentColor,transparent 68%);
  opacity:0;transition:opacity .1s;
}
.pad.active{opacity:1;border-color:rgba(94,231,255,.55);box-shadow:0 0 18px rgba(94,231,255,.14) inset}
.pad.active .pk{color:#dff8ff}
.pad.active::before{opacity:.8;box-shadow:0 0 12px currentColor}
.pad.sleep{opacity:.25}
.pad.section{opacity:1}
.pad.pressed{border-color:#fff;background:rgba(94,231,255,.14);box-shadow:0 0 28px rgba(94,231,255,.28)}
.pad.pressed i{opacity:.32}
.pad.pressed .pk{color:#fff}

/* ---------------- overlays ---------------- */
.overlay{
  position:absolute;inset:0;display:flex;align-items:center;justify-content:center;
  opacity:0;visibility:hidden;transition:opacity .4s ease, visibility .4s;
  padding:clamp(18px,4vw,60px);
  background:
    radial-gradient(ellipse at 68% 42%, rgba(15,24,54,.42), transparent 60%),
    linear-gradient(90deg, rgba(2,3,10,.92) 0%, rgba(2,3,10,.62) 48%, rgba(2,3,10,.18) 100%);
  backdrop-filter:blur(2px);
  overflow:auto;
}
.overlay.show{opacity:1;visibility:visible}
.overlay::before{
  content:"";position:absolute;inset:0;pointer-events:none;
  background-image:
    linear-gradient(rgba(130,180,255,.045) 1px,transparent 1px),
    linear-gradient(90deg,rgba(130,180,255,.045) 1px,transparent 1px);
  background-size:64px 64px;
  mask-image:radial-gradient(ellipse at 50% 50%,#000 10%,transparent 78%);
}
.start-grid{
  width:min(1180px,100%);display:grid;grid-template-columns:1.2fr .8fr;
  gap:clamp(28px,5vw,90px);align-items:center;position:relative;
}
.eyebrow{
  display:flex;align-items:center;gap:10px;font-family:var(--mono);
  font-size:9px;letter-spacing:.32em;color:var(--cyan);text-transform:uppercase;
}
.eyebrow i{width:24px;height:1px;background:var(--cyan);box-shadow:0 0 8px var(--cyan)}
.start-copy h1{
  margin:18px 0 10px;font-size:clamp(88px,13.4vw,190px);line-height:.72;
  font-weight:900;letter-spacing:-.065em;color:#fff;
  text-shadow:
    0 0 1px #fff,
    0 0 34px rgba(94,231,255,.32),
    7px 7px 0 rgba(255,95,210,.12),
    -5px -5px 0 rgba(94,231,255,.1);
  position:relative;
}
.start-copy h1::after{
  content:"";position:absolute;left:2px;right:16%;top:47%;height:2px;
  background:linear-gradient(90deg,transparent,rgba(94,231,255,.65),transparent);
  mix-blend-mode:screen;animation:scan 5s linear infinite;
}
@keyframes scan{0%,100%{opacity:.2;transform:translateY(-0.5em)}50%{opacity:.8;transform:translateY(1.3em)}}
.tagline{
  margin:0 0 26px;font-size:clamp(15px,1.5vw,20px);line-height:1.55;color:#b8c7db;
  max-width:34ch;font-weight:300;
}
.specs{
  display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;
  border-top:1px solid var(--line);border-bottom:1px solid var(--line);
  padding:14px 0;margin-bottom:26px;max-width:560px;
}
.specs span{display:block;font-family:var(--mono);font-size:8px;letter-spacing:.2em;color:var(--muted);margin-bottom:6px}
.specs b{font-family:var(--mono);font-size:12px;letter-spacing:.08em;font-weight:600;color:#e7f3ff}
.cta{
  display:inline-flex;align-items:center;gap:22px;justify-content:space-between;
  min-width:260px;padding:16px 22px;border:1px solid rgba(94,231,255,.52);
  background:linear-gradient(90deg,rgba(94,231,255,.16),rgba(147,116,255,.1));
  font-family:var(--mono);font-size:11px;letter-spacing:.26em;color:#eaffff;
  box-shadow:0 0 40px rgba(94,231,255,.12) inset,0 0 30px rgba(94,231,255,.06);
  transition:.22s;position:relative;overflow:hidden;
}
.cta::after{
  content:"";position:absolute;inset:0;background:linear-gradient(100deg,transparent 20%,rgba(255,255,255,.18) 50%,transparent 80%);
  transform:translateX(-120%);transition:transform .6s;
}
.cta:hover:not(:disabled)::after{transform:translateX(120%)}
.cta:hover:not(:disabled){border-color:var(--cyan);box-shadow:0 0 50px rgba(94,231,255,.22),0 0 30px rgba(94,231,255,.08) inset;transform:translateY(-2px)}
.cta:disabled{opacity:.45;cursor:wait}
.cta i{font-style:normal;font-size:17px;line-height:1;color:var(--cyan)}
.cta.small{min-width:180px;padding:13px 18px}
.loadbar{height:2px;width:min(300px,100%);background:rgba(140,190,255,.14);margin-top:12px;overflow:hidden}
.loadbar b{display:block;height:100%;width:0%;background:var(--cyan);box-shadow:0 0 12px var(--cyan);transition:width .2s}
.hint{margin:16px 0 0;font-family:var(--mono);font-size:9px;line-height:1.7;letter-spacing:.08em;color:#687792}

.start-side{display:flex;flex-direction:column;gap:14px}
.panel{
  border:1px solid var(--line);background:var(--panel);backdrop-filter:blur(12px);
  padding:20px 20px 18px;position:relative;
}
.panel::before{
  content:"";position:absolute;left:-1px;top:-1px;width:35px;height:1px;background:var(--cyan);
  box-shadow:0 0 10px var(--cyan);
}
.panel-title{font-family:var(--mono);font-size:9px;letter-spacing:.28em;color:var(--cyan);margin-bottom:16px}
.keyrow{display:grid;grid-template-columns:repeat(8,1fr);gap:4px;margin-bottom:12px}
kbd{
  display:flex;align-items:center;justify-content:center;aspect-ratio:1;min-height:28px;
  border:1px solid rgba(150,195,255,.28);background:rgba(10,16,34,.8);
  font-family:var(--mono);font-size:10px;color:#cfe6ff;border-radius:3px;
  box-shadow:0 2px 0 rgba(0,0,0,.35);
}
.panel p{margin:0;font-size:12px;line-height:1.6;color:#9cadc4}
.touchline{display:flex;align-items:center;gap:8px;margin-top:14px;font-family:var(--mono);font-size:8px;letter-spacing:.18em;color:var(--muted)}
.touchicon{width:11px;height:16px;border:1px solid var(--muted);border-radius:3px;position:relative}
.touchicon::after{content:"";position:absolute;left:4px;top:3px;width:2px;height:4px;background:var(--cyan)}
.syslist{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:10px}
.syslist li{display:flex;justify-content:space-between;font-family:var(--mono);font-size:9px;letter-spacing:.12em;color:var(--muted);border-bottom:1px dashed rgba(140,190,255,.1);padding-bottom:9px}
.syslist li:last-child{border:0;padding:0}
.syslist b{color:#d7e9ff;font-weight:500}
.credit{font-family:var(--mono);font-size:8px;line-height:1.8;letter-spacing:.14em;color:#4d5a72;text-align:right;margin-top:2px}

/* modal / results */
.modal,.results{
  width:min(720px,100%);position:relative;
  border:1px solid var(--line);background:rgba(5,8,19,.84);backdrop-filter:blur(18px);
  padding:clamp(24px,4vw,48px);box-shadow:0 30px 90px rgba(0,0,0,.6);
  animation:modalIn .45s cubic-bezier(.2,.7,.2,1) both;
}
@keyframes modalIn{from{opacity:0;transform:translateY(18px) scale(.98)}to{opacity:1;transform:none}}
.modal h2,.results h2{
  margin:16px 0 4px;font-size:clamp(48px,8vw,92px);line-height:.86;letter-spacing:-.04em;font-weight:900;
}
.modal-sub{margin:10px 0 28px;font-family:var(--mono);font-size:10px;letter-spacing:.18em;color:var(--muted)}
.btnrow{display:flex;gap:10px;flex-wrap:wrap}
.ghost{
  padding:13px 18px;border:1px solid rgba(140,190,255,.22);
  font-family:var(--mono);font-size:10px;letter-spacing:.2em;color:#9fb4cd;transition:.2s;
}
.ghost:hover{border-color:var(--cyan);color:#eaffff;background:rgba(94,231,255,.05)}

.result-head{display:flex;justify-content:space-between;align-items:flex-start;gap:24px}
#rank{
  font-size:clamp(90px,15vw,170px);line-height:.72;font-weight:900;letter-spacing:-.07em;
  color:#fff;text-shadow:0 0 40px rgba(94,231,255,.6),0 0 110px rgba(255,95,210,.35);
  font-style:italic;
}
.result-stats{
  display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line);
  border:1px solid var(--line);margin:26px 0 24px;
}
.result-stats>div{background:rgba(6,10,23,.92);padding:14px 14px 13px;min-height:64px}
.result-stats span{display:block;font-family:var(--mono);font-size:8px;letter-spacing:.18em;color:var(--muted);margin-bottom:7px}
.result-stats b{font-family:var(--mono);font-size:20px;letter-spacing:.03em;font-weight:600;color:#eaf6ff}
.result-stats .bigstat{grid-column:span 2;padding:18px}
.result-stats .bigstat b{font-size:clamp(24px,3vw,34px);color:#fff;text-shadow:0 0 22px rgba(94,231,255,.35)}
.result-foot{display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}
.fc{
  font-family:var(--mono);font-size:9px;letter-spacing:.26em;color:var(--cyan);
  border:1px solid rgba(94,231,255,.45);padding:8px 12px;opacity:0;transform:translateY(4px);
  transition:.3s;
}
.fc.on{opacity:1;transform:none;box-shadow:0 0 20px rgba(94,231,255,.18)}

#toast{
  position:absolute;left:50%;top:22%;transform:translate(-50%,-8px);
  font-family:var(--mono);font-size:11px;letter-spacing:.28em;color:#fff;
  background:rgba(4,8,20,.8);border:1px solid var(--line);padding:10px 16px;
  opacity:0;transition:.3s;pointer-events:none;white-space:nowrap;
}
#toast.on{opacity:1;transform:translate(-50%,0)}

#rotateHint{
  display:none;position:absolute;left:50%;bottom:calc(max(12px,env(safe-area-inset-bottom)) + 68px);
  transform:translateX(-50%);font-family:var(--mono);font-size:8px;letter-spacing:.18em;
  color:var(--muted);pointer-events:none;
}
#rotateHint span{color:var(--cyan);font-size:12px}

/* ---------------- responsive ---------------- */
@media (max-width:900px){
  .overlay{background:linear-gradient(180deg,rgba(2,3,10,.94),rgba(2,3,10,.72) 55%,rgba(2,3,10,.9));align-items:flex-start;padding-top:6vh}
  .start-grid{grid-template-columns:1fr;gap:26px}
  .start-side{display:grid;grid-template-columns:1fr 1fr;gap:10px}
  .credit{grid-column:1/-1}
  .start-copy h1{font-size:clamp(76px,19vw,130px)}
  .specs{max-width:none}
  .topbar{grid-template-columns:1fr 1.3fr;gap:14px}
  .track-wrap{grid-column:1/-1;grid-row:2;order:3}
  .scoreblock{position:absolute;right:clamp(14px,4vw,30px);top:clamp(14px,4vw,30px)}
  .left-hud{bottom:clamp(100px,14vh,150px)}
  #comboHud{top:40%}
  #judge{top:52%}
  #pads{width:calc(100% - 20px);gap:4px}
}

@media (max-width:620px){
  .start-side{grid-template-columns:1fr}
  .credit{text-align:left}
  .specs{grid-template-columns:repeat(2,1fr)}
  .start-copy h1{font-size:clamp(70px,23vw,110px)}
  .start-copy .tagline{font-size:14px;margin-bottom:20px}
  .cta{width:100%;min-width:0}
  .panel{padding:15px}
  .panel:nth-child(2){display:none}
  .result-stats{grid-template-columns:repeat(2,1fr)}
  .result-stats .bigstat{grid-column:span 2}
  #rank{font-size:80px}
  .modal,.results{padding:22px}
  .topbar{padding-top:4px}
  .brand-title{font-size:16px}
  .score{font-size:22px}
  .left-hud{display:none}
  #pauseBtn{width:34px;height:34px;bottom:calc(max(10px,env(safe-area-inset-bottom)) + 62px);right:12px}
  .pad{height:50px;border-radius:4px}
  .pad .pk{font-size:10px}
