let last = performance.now();
let menuT = 0;
let lastPadAlign = 0;

function frame(now) {
  const dt = Math.min(0.05, Math.max(0, (now - last) / 1000));
  last = now;
  menuT += dt;

  if (gameState === 'playing' && audio.loaded) {
    const t = audio.time;
    refreshSection(t);
    updateNotes(t);
    updateHUD(t);
    if (t >= END_TIME) finishGame();
    scene.animate(dt, t, true);
    alignPads();
  } else if (gameState === 'paused') {
    const t = audio.time;
    scene.animate(dt, t, true);
  } else if (gameState === 'results') {
    scene.animate(dt, menuT, false);
  } else {
    scene.animate(dt, menuT, false);
  }

  if ((gameState === 'playing' || gameState === 'paused') && now - lastPadAlign > 70) {
    alignPads();
    lastPadAlign = now;
  }
  scene.render();
  requestAnimationFrame(frame);
}

