 .loadbar{height:2px;width:min(300px,100%);background:rgba(140,190,255,.14);margin-top:12px;overflow:hidden}
 .loadbar b{display:block;height:100%;width:0%;background:var(--cyan);box-shadow:0 0 12px var(--cyan);transition:width .2s}
+.best-line{display:none;margin:10px 0 0;font-family:var(--mono);font-size:8px;letter-spacing:.18em;color:var(--muted)}
+.best-line b{color:#dff6ff;font-weight:500;letter-spacing:.1em}
 .hint{margin:16px 0 0;font-family:var(--mono);font-size:9px;line-height:1.7;letter-spacing:.08em;color:#687792}

 .start-side{display:flex;flex-direction:column;gap:14px}
 .panel{

input.newString:
.result-foot .btnrow .cta,.result-foot .btnrow .ghost{width:100%;min-width:0}
#resultScreen.show,#pauseScreen.show{align-items:center;padding-top:18px}
.best-line{display:block}
.modal .btnrow{display:grid;grid-template-columns:1fr 1fr;width:100%}

input.oldString:
.result-foot .btnrow .cta,.result-foot .btnrow .ghost{width:100%;min-width:0}
#resultScreen.show,#pauseScreen.show{align-items:center;padding-top:18px}
.modal .btnrow{display:grid;grid-template-columns:1fr 1fr;width:100%}

