628:     state.time = t;
629:     state.playing = playing;
630:     const v = state.view, tg = state.target;
631: 
632:     // smooth view
633:     const k = 1 - Math.exp(-dt * 2.2);
634:     v.rotY += (tg.rotY - v.rotY) * k;
635:     v.rotZ += (tg.rotZ - v.rotZ) * k;
636:     v.tilt += (tg.tilt - v.tilt) * k;
637:     v.spread += (tg.spread - v.spread) * k;
638:     v.y += (tg.y - v.y) * k;
639:     v.camZ += (tg.camZ - v.camZ) * k;
640:     v.camY += (tg.camY - v.camY) * k;
641:     v.spin += (tg.spin - v.spin) * k;
642:     bloom.strength += (tg.bloom - bloom.strength) * k;
643: 
644:     const beatPhase = ((t - 0.535) / 0.6 + 8) % 1;
645:     const pulse = Math.exp(-beatPhase * 5.2);
646:     state.pulse = pulse;
647: 
648:     // stage motion
649:     stage.position.y = v.y + Math.sin(t * 0.65) * 0.035 + pulse * 0.03;
650:     stage.rotation.y = v.rotY + Math.sin(t * 0.22) * 0.02 + Math.sin(t * 0.09) * v.spin;
651:     stage.rotation.z = v.rotZ + Math.sin(t * 0.37) * 0.006;
652:     stage.rotation.x = v.tilt + Math.sin(t * 0.29) * 0.006;
653: 
654:     // lane positions respond to spread
655:     for (let i = 0; i < 8; i++) {
656:       const l = lanes[i];
657:       const x = (i - 3.5) * state.spacing * v.spread;
658:       l.baseX = x;
659:       l.group.position.x = x;
660:       l.group.position.z = ARC * x * x;
661:       state.laneXNow[i] = x;
662: 
663:       const targetOpacity = l.active * (i % 2 ? 0.86 : 0.96);
664:       l.line.material.opacity += (targetOpacity * 0.58 - l.line.material.opacity) * (1 - Math.exp(-dt * 3.5));
665:       l.beam.material.opacity += (l.active * (0.065 + pulse * 0.03) - l.beam.material.opacity) * (1 - Math.exp(-dt * 3.5));
666:       l.ring.material.opacity += ((state.active.has(i) ? 0.95 : 0.085) - l.ring.material.opacity) * (1 - Math.exp(-dt * 3.5));
667:       l.glow.material.opacity += ((state.active.has(i) ? 0.14 : 0.008) + l.flash * 0.3 - l.glow.material.opacity) * (1 - Math.exp(-dt * 8));
668: 
669:       l.flash = Math.max(0, l.flash - dt * 3.4);
670:       const rs = state.ringScaleNow * (1 + pulse * 0.045 * (0.4 + state.energy) + l.flash * 0.22);
671:       l.ring.scale.set(rs, rs, 1);
672:       l.ring.material.color.copy(l.targetColor).lerp(white, l.flash * 0.8);
673:       l.glow.material.color.copy(l.targetColor).lerp(white, l.flash * 0.5);
674:       l.line.material.color.copy(l.targetColor).lerp(white, 0.14 + l.flash * 0.32);
675:       l.beam.material.color.copy(l.targetColor);
676:     }
677:     hitLine.scale.x = (state.spacing * 7 + 2.35) * v.spread;
678:     hitLine.material.opacity = 0.45 + pulse * 0.3 + state.energy * 0.15;
679: 
680:     // camera
681:     const camX = state.mouse.x * 0.55;
682:     const camY = v.camY + state.mouse.y * 0.18;
683:     camera.position.x += (camX - camera.position.x) * (1 - Math.exp(-dt * 2));
684:     camera.position.y += (camY - camera.position.y) * (1 - Math.exp(-dt * 2));
685:     camera.position.z += (v.camZ - camera.position.z) * (1 - Math.exp(-dt * 2));
686:     if (state.shake > 0.0005) {
687:       camera.position.x += (Math.random() - .5) * state.shake;
688:       camera.position.y += (Math.random() - .5) * state.shake;
689:       state.shake *= Math.exp(-dt * 10);
690:     }
691:     camera.lookAt(0, 4.05, 0);
692: 
693:     // background
694:     stars.rotation.y += dt * 0.006;
695:     stars2.rotation.y -= dt * 0.004;
696:     dust.rotation.y += dt * 0.012;
697:     neb1.position.x = -16 + Math.sin(t * 0.05) * 2;
698:     neb2.position.y = 1 + Math.sin(t * 0.07 + 1) * 2;
699:     for (let i = 0; i < bgRings.length; i++) {
700:       bgRings[i].rotation.z += dt * (0.02 + i * 0.012);
701:       bgRings[i].rotation.y += dt * 0.008;
702:     }
703:     for (const s of shards) {
704:       s.rotation.x += s.userData.spin.x * dt;
705:       s.rotation.y += s.userData.spin.y * dt;
706:       s.rotation.z += s.userData.spin.z * dt;
707:       s.position.y += Math.sin(t * 0.4 + s.position.x) * dt * 0.06;
708:     }
709: 
710:     // particles
711:     let activeP = false;
712:     for (let i = 0; i < PMAX; i++) {
713:       if (pLife[i] <= 0) continue;
714:       activeP = true;
715:       pLife[i] -= dt;
716:       if (pLife[i] <= 0) {
717:         pPos[i * 3 + 1] = -999;
718:         continue;
719:       }
720:       pVel[i * 3] *= 0.972;
721:       pVel[i * 3 + 1] -= 2.4 * dt;
722:       pVel[i * 3 + 2] *= 0.972;
723:       pPos[i * 3] += pVel[i * 3] * dt;
724:       pPos[i * 3 + 1] += pVel[i * 3 + 1] * dt;
725:       pPos[i * 3 + 2] += pVel[i * 3 + 2] * dt;
726:       const a = Math.max(0, pLife[i] / pMax[i]);
727:       pCol[i * 3] *= 0.988;
728:       pCol[i * 3 + 1] *= 0.988;
729:       pCol[i * 3 + 2] *= 0.988;
730:       if (a < 0.25) {
731:         pCol[i * 3] *= a / 0.25; pCol[i * 3 + 1] *= a / 0.25; pCol[i * 3 + 2] *= a / 0.25;
732:       }
733:     }
734:     if (activeP) {
735:       pGeo.attributes.position.needsUpdate = true;
736:       pGeo.attributes.color.needsUpdate = true;
737:     }
738: 
739:     // shockwaves
740:     for (const s of shocks) {
741:       if (s.life <= 0) continue;
742:       s.life -= dt;
743:       const f = 1 - Math.max(0, s.life / s.max);
744:       const sc = 0.75 + f * s.scale;
745:       s.sprite.scale.set(sc, sc, 1);
746:       s.sprite.material.opacity = (1 - f) * 0.9;
747:       if (s.life <= 0) s.sprite.visible = false;
748:     }
749: 
750:     // tiny idle shimmer
751:     for (let i = 0; i < 8; i++) {
752:       if (!state.active.has(i) && Math.random() < dt * 0.5) lanes[i].flash = Math.max(lanes[i].flash, 0.15);
753:     }
754:   }
