// ---------------------------------------------------------------- lane flourishes
// Visual-only events for lanes that are not playable in a section. They keep the
// field alive without adding notes: a light sweeps up the hidden lane line or the
// lane ring bounces on the beat.
(() => {
  const SETS = { 4: [2, 3, 4, 5], 6: [1, 2, 3, 4, 5, 6], 8: [0, 1, 2, 3, 4, 5, 6, 7] };
  const beat = 60 / CHART.song.bpm;
  const ghosts = [];
  CHART.sections.forEach((sec, index) => {
    const active = new Set(SETS[sec.keys] || SETS[8]);
    const idle = SETS[8].filter((lane) => !active.has(lane));
    if (!idle.length) return;
    const entry = Math.min(sec.end - 0.2, sec.start + 0.04);
    if (index > 0) {
      idle.forEach((lane, i) => ghosts.push({ t: entry + i * 0.06, lane, type: 'sweep' }));
    }
    let n = 0;
    for (let t = sec.start + beat * 2; t < sec.end - 0.5; t += beat * 4) {
      ghosts.push({ t: Number(t.toFixed(3)), lane: idle[n % idle.length], type: n % 3 === 1 ? 'bounce' : 'sweep' });
      n++;
    }
  });
  ghosts.sort((a, b) => a.t - b.t);
  CHART.ghosts = ghosts;
})();
```

