// --------------------------------------------------------------- lane flourishes
// The hidden lanes are not dead space. These visual-only events are charted on
// the beat grid: a light sweeps up the line or the ring bounces when a phrase
// changes. They never add notes, so the playable lane count stays honest.
(() => {
  const SETS = { 4: [2, 3, 4, 5], 6: [1, 2, 3, 4, 5, 6], 8: [0, 1, 2, 3, 4, 5, 6, 7] };
  const beat = 60 / CHART.song.bpm;
  const ghosts = [];
  CHART.sections.forEach((sec, index) => {
    const active = new Set(SETS[sec.keys] || SETS[8]);
    const idle = SETS[8].filter((lane) => !active.has(lane));
    if (!idle.length) return;
    // lanes that just went dormant send a sweep up as the section changes
    if (index > 0) {
      idle.forEach((lane, i) => {
        ghosts.push({ t: Number((sec.start + 0.05 + i * 0.055).toFixed(3)), lane, type: 'sweep' });
      });
    }
    // and the remaining idle lanes keep breathing with the phrase
    let n = 0;
    for (let t = sec.start + beat * 2; t < sec.end - 0.45; t += beat * 4) {
      ghosts.push({
        t: Number(t.toFixed(3)),
        lane: idle[n % idle.length],
        type: n % 3 === 1 ? 'bounce' : 'sweep',
      });
      n++;
    }
  });
  ghosts.sort((a, b) => a.t - b.t);
  CHART.ghosts = ghosts;
})();

