164: /* ---------------- touch / key pads ----------------
165:    The pads are invisible tap zones placed on top of the 3D hit rings. The ring
166:    itself is the hit position, so tapping the ring is tapping the note. */
167: #pads{
168:   position:fixed;inset:0;z-index:4;
