import { writeFileSync } from 'node:fs';
const base = 'http://127.0.0.1:9222';
const target = (await (await fetch(base + '/json/list')).json()).find(t => t.type === 'page');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0; const pending = new Map(); const logs = [];
ws.onmessage = (e) => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { const p = pending.get(m.id); pending.delete(m.id); m.error ? p.reject(new Error(JSON.stringify(m.error))) : p.resolve(m.result); } else if (m.method === 'Runtime.exceptionThrown') logs.push('EXCEPTION ' + (m.params.exceptionDetails.exception?.description || m.params.exceptionDetails.text)); };
const send = (method, params = {}) => new Promise((resolve, reject) => { const mid = ++id; pending.set(mid, { resolve, reject }); ws.send(JSON.stringify({ id: mid, method, params })); });
const sleep = ms => new Promise(r => setTimeout(r, ms));
const ev = async expr => { const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || r.exceptionDetails.text); return r.result?.value; };
const shot = async p => { const r = await send('Page.captureScreenshot', { format: 'png' }); writeFileSync(p, Buffer.from(r.data, 'base64')); };
const click = async (x, y) => { await send('Input.dispatchMouseEvent', { type: 'mousePressed', x, y, button: 'left', clickCount: 1 }); await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x, y, button: 'left', clickCount: 1 }); };

await send('Runtime.enable'); await send('Page.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });
await send('Emulation.setTouchEmulationEnabled', { enabled: true, maxTouchPoints: 5 });
await send('Page.navigate', { url: 'http://localhost:3002/' });
await sleep(4000);
let pt = await ev(`(() => { const r = document.querySelector('.track-card[data-track="world"]').getBoundingClientRect(); return {x:r.x+r.width/2,y:r.y+r.height/2}; })()`);
await click(pt.x, pt.y); await sleep(3000);
pt = await ev(`(() => { const r = document.getElementById('startBtn').getBoundingClientRect(); return {x:r.x+r.width/2,y:r.y+r.height/2}; })()`);
await click(pt.x, pt.y); await sleep(2600);
await shot('/tmp/opencode/mobile-play.png');
const probe = await ev(`(() => {
  const s=window.__cryout.scene; const pts=s.laneScreenPoints(); const out=[];
  for(let lane=0;lane<8;lane++){
    const p=document.querySelector('.pad[data-lane="'+lane+'"]');
    if(p.classList.contains('sleep')) continue;
    const g=pts[lane]; const row=[];
    for(const f of [0,0.3,0.6,0.9]){
      const x=g.x+(g.topX-g.x)*f, y=g.y+(g.topY-g.y)*f;
      const pad=document.elementFromPoint(x,y)?.closest?.('.pad');
      row.push(f+':'+(pad?.dataset?.lane??'X'));
    }
    const r=p.getBoundingClientRect();
    out.push({lane, row:row.join(' '), rect:[Math.round(r.x),Math.round(r.y),Math.round(r.width),Math.round(r.height)]});
  }
  return out;
})()`);
console.log(JSON.stringify(probe, null, 1));
// two-finger tap on two live lanes
const pts = await ev(`(() => { const s=window.__cryout.scene.laneScreenPoints(); return s.map(g=>({x:g.x*0.6+g.topX*0.4, y:g.y*0.6+g.topY*0.4})); })()`);
const live = await ev(`[...document.querySelectorAll('.pad:not(.sleep)')].map(p=>+p.dataset.lane)`);
const touches = live.slice(0,2).map((lane, i) => ({ x: pts[lane].x, y: pts[lane].y, radiusX: 8, radiusY: 8, id: i + 1 }));
if (touches.length) {
  await send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: touches });
  await sleep(140);
  await send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
}
console.log('PADS', await ev(`[...document.querySelectorAll('.pad')].filter(p=>p.classList.contains('pressed')).length`));
console.log('LOGS', logs);
ws.close();

