685: function alignPads(ahead = new Set()) {
686:   // Long touch strips follow the projected lane direction. Tapping anywhere
687:   // along the lane hits that lane, and a lane with an incoming note is made
688:   // live before its section actually starts.
689:   const active = new Set(currentSection ? activeLanesFor(currentSection.keys) : []);
690:   for (const lane of ahead) active.add(lane);
691:   for (let i = 0; i < 8; i++) {
692:     const g = scene.laneScreenGeometry(i);
693:     const left = i > 0 ? g.x - scene.laneScreenGeometry(i - 1).x : g.x - scene.laneScreenGeometry(1).x;
694:     const right = i < 7 ? scene.laneScreenGeometry(i + 1).x - g.x : g.x - scene.laneScreenGeometry(6).x;
695:     const gap = Math.max(24, Math.min(Math.abs(left), Math.abs(right)));
696:     const width = Math.max(40, Math.min(176, gap * 0.94));
697:     // The strip is anchored at the hit circle and runs straight up the lane;
698:     // a small tail below the ring gives thumbs somewhere to land naturally.
699:     const bottom = g.y + 26;
700:     const top = Math.max(6, Math.min(bottom - 110, g.topY));
