import { writeFileSync } from 'node:fs';
const base = 'http://127.0.0.1:9222';
const target = (await (await fetch(base + '/json/list')).json()).find(t => t.type === 'page');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0; const pending = new Map(); const logs = [];
ws.onmessage = (e) => {
  const m = JSON.parse(e.data);
  if (m.id && pending.has(m.id)) { const p = pending.get(m.id); pending.delete(m.id); m.error ? p.reject(new Error(JSON.stringify(m.error))) : p.resolve(m.result); }
  else if (m.method === 'Runtime.exceptionThrown') logs.push('EXCEPTION ' + (m.params.exceptionDetails.exception?.description || m.params.exceptionDetails.text));
  else if (m.method === 'Runtime.consoleAPICalled' && m.params.type === 'error') logs.push('console.error ' + m.params.args.map(a => a.value ?? a.description).join(' '));
};
const send = (method, params = {}) => new Promise((resolve, reject) => { const mid = ++id; pending.set(mid, { resolve, reject }); ws.send(JSON.stringify({ id: mid, method, params })); });
const sleep = ms => new Promise(r => setTimeout(r, ms));
const ev = async expr => { const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description || r.exceptionDetails.text); return r.result?.value; };
const click = async (x, y) => { await send('Input.dispatchMouseEvent', { type: 'mousePressed', x, y, button: 'left', clickCount: 1 }); await send('Input.dispatchMouseEvent', { type: 'mouseReleased', x, y, button: 'left', clickCount: 1 }); };
const clickSel = async sel => { const pt = await ev(`(() => { const r=document.querySelector(${JSON.stringify(sel)}).getBoundingClientRect(); return {x:r.x+r.width/2,y:r.y+r.height/2}; })()`); await click(pt.x, pt.y); };
const shot = async p => { const r = await send('Page.captureScreenshot', { format: 'png' }); writeFileSync(p, Buffer.from(r.data, 'base64')); };

async function boot({ width, height, mobile }) {
  await send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: mobile ? 2 : 1, mobile });
  await send('Emulation.setTouchEmulationEnabled', { enabled: mobile, maxTouchPoints: 5 });
  await send('Page.navigate', { url: 'http://localhost:3002/' });
  await sleep(3800);
  await ev(`localStorage.clear()`);
  await send('Page.reload');
  await sleep(3600);
}

async function autoplayToResults(screenshotPrefix, heldTouch) {
  if (heldTouch) await send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: 30, y: 760, radiusX: 8, radiusY: 8, id: 1 }] });
  const res = await ev(`(() => {
    const c = window.__cryout;
    const notes = [...c.chart.notes].sort((a, b) => a.t - b.t);
    let pressed = 0;
    for (const n of notes) {
      c.audio.startAt = c.audio.ctx.currentTime - n.t;
      const before = c.stats.judged;
      c.pressLane(n.lane, n.type === 'hold');
      if (c.stats.judged > before) pressed++;
    }
    c.audio.startAt = c.audio.ctx.currentTime - (c.chart.song.chartEnd + 0.05);
    return { notes: notes.length, pressed };
  })()`);
  // loading screen mid-animation
  for (let i = 0; i < 60; i++) { if ((await ev(`document.getElementById('resultLoading').classList.contains('show')`))) break; await sleep(60); }
  await sleep(650);
  const load = await ev(`({shown:document.getElementById('resultLoading').classList.contains('show'), pct:document.getElementById('loadPct').textContent, rank:document.getElementById('loadRank').textContent, w:document.getElementById('loadProgress').style.width})`);
  await shot(`/tmp/opencode/${screenshotPrefix}-loading.png`);
  for (let i = 0; i < 100; i++) { if ((await ev(`document.getElementById('resultScreen').classList.contains('show')`))) break; await sleep(80); }
  await sleep(1400);
  const result = await ev(`(() => {
    const c = window.__cryout;
    const root = document.getElementById('resultScreen');
    const box = root.querySelector('.results');
    const r = box.getBoundingClientRect();
    const retry = document.getElementById('retryBtn').getBoundingClientRect();
    const menu = document.getElementById('menuBtn').getBoundingClientRect();
    return {
      state: c.state,
      stats: { judged: c.stats.judged, perfect: c.stats.perfect, miss: c.stats.miss, dropped: c.stats.dropped, score: c.stats.score },
      shown: root.classList.contains('show'),
      rank: document.getElementById('rank').textContent,
      score: document.getElementById('finalScore').textContent,
      acc: document.getElementById('finalAcc').textContent,
      tag: document.getElementById('resultTag').textContent,
      track: document.getElementById('resultTrack').textContent,
      graph: document.getElementById('comboLine').getAttribute('d').length,
      fitsViewport: r.top >= -1 && r.bottom <= innerHeight + 1,
      box: [Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height)],
      view: [innerWidth, innerHeight],
      retryVisible: retry.top >= 0 && retry.bottom <= innerHeight,
      menuVisible: menu.top >= 0 && menu.bottom <= innerHeight,
      scrollable: box.scrollHeight > box.clientHeight,
      overflow: box.scrollWidth > box.clientWidth,
    };
  })()`);
  await shot(`/tmp/opencode/${screenshotPrefix}-results.png`);
  if (heldTouch) await send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
  return { res, load, result };
}

await send('Runtime.enable'); await send('Page.enable');

// ---------------- desktop: world track ----------------
await boot({ width: 1440, height: 900, mobile: false });
const menu = await ev(`(() => {
  const cards = [...document.querySelectorAll('.track-card')].map(c => ({ id: c.dataset.track, active: c.classList.contains('active'), selected: c.getAttribute('aria-selected') }));
  return { state: window.__cryout.state, disabled: document.getElementById('startBtn').disabled, cards, track: window.__cryout.chart.song.shortTitle };
})()`);
await clickSel('.track-card[data-track="world"]'); await sleep(2800);
const selected = await ev(`({ state:window.__cryout.state, track:window.__cryout.chart.song.shortTitle, notes:window.__cryout.notes.length, label:document.getElementById('startBtnLabel').textContent, disabled:document.getElementById('startBtn').disabled, specs:[document.getElementById('startTrack').textContent, document.getElementById('startLanes').textContent, document.getElementById('startLength').textContent], accent:getComputedStyle(document.documentElement).getPropertyValue('--track-accent').trim() })`);
await clickSel('#startBtn'); await sleep(2600);
const liveWorld = await ev(`(() => { const c=window.__cryout; const pads=[...document.querySelectorAll('.pad')]; return { state:c.state, section:document.getElementById('sectionName').textContent, keys:document.getElementById('keysCount').textContent, live:pads.filter(p=>!p.classList.contains('sleep')).map(p=>+p.dataset.lane), city:+c.scene.state.city.toFixed(2), cityVisible:!!c.scene.state.city, hudTrack:document.getElementById('hudTrack').textContent }; })()`);
await shot('/tmp/opencode/final-world-play.png');
const world = await autoplayToResults('final-world', true);
console.log('DESKTOP MENU', JSON.stringify(menu));
console.log('DESKTOP SELECT', JSON.stringify(selected));
console.log('DESKTOP PLAY', JSON.stringify(liveWorld));
console.log('DESKTOP AUTOPLAY', JSON.stringify(world.res));
console.log('DESKTOP LOADING', JSON.stringify(world.load));
console.log('DESKTOP RESULT', JSON.stringify(world.result));

// menu from results
await clickSel('#menuBtn'); await sleep(1500);
const back = await ev(`({ state:window.__cryout.state, start:document.getElementById('startScreen').classList.contains('show'), selected:[...document.querySelectorAll('.track-card')].find(c=>c.classList.contains('active'))?.dataset.track })`);
