}
#resultLoading.transition::before{opacity:.5;mask-image:radial-gradient(ellipse at 50% 50%,#000 0%,transparent 68%)}
.compile{
  width:min(820px,100%);display:grid;grid-template-columns:auto 1fr;align-items:center;
  gap:clamp(20px,5vw,56px);position:relative;
}
.compile-orbit{width:clamp(120px,18vw,180px);aspect-ratio:1;position:relative;display:grid;place-items:center}
.compile-orbit i{position:absolute;inset:0;border-radius:50%;border:1px solid rgba(94,231,255,.28)}
.compile-orbit i:nth-child(1){border-style:dashed;animation:compileSpin 7s linear infinite;box-shadow:0 0 30px rgba(94,231,255,.1) inset}
.compile-orbit i:nth-child(2){inset:14%;border-color:rgba(255,95,210,.3);animation:compileSpin 4.4s linear infinite reverse}
.compile-orbit i:nth-child(3){inset:30%;border-color:rgba(94,231,255,.4);animation:compilePulse 1.8s ease-in-out infinite}
@keyframes compileSpin{to{transform:rotate(360deg)}}
@keyframes compilePulse{0%,100%{transform:scale(1);opacity:.7}50%{transform:scale(1.12);opacity:1}}
.compile-core{
  width:44%;aspect-ratio:1;border-radius:50%;display:grid;place-items:center;position:relative;z-index:1;
