}
.compile-core span{font-family:var(--mono);font-size:clamp(22px,3.4vw,34px);font-weight:800;font-style:italic;color:#fff;text-shadow:0 0 20px rgba(94,231,255,.8)}
.compile-copy h2{margin:8px 0 6px;font-size:clamp(34px,5.2vw,64px);line-height:.86;letter-spacing:-.045em;font-weight:900}
.compile-copy h2 span{color:transparent;-webkit-text-stroke:1px rgba(94,231,255,.7);text-shadow:0 0 32px rgba(94,231,255,.25)}
.compile-copy p{margin:0 0 22px;font-family:var(--mono);font-size:9px;letter-spacing:.2em;color:var(--muted)}
.compile-progress{height:3px;background:rgba(140,190,255,.14);position:relative;overflow:hidden}
.compile-progress b{display:block;height:100%;width:0%;background:linear-gradient(90deg,var(--cyan),var(--magenta));box-shadow:0 0 16px var(--cyan)}
.compile-meta{display:flex;justify-content:space-between;margin-top:9px;font-family:var(--mono);font-size:8px;letter-spacing:.2em;color:var(--muted)}
.compile-meta span:first-child{color:var(--cyan)}
